import boto3
import os
sns = boto3.client('sns')
bus = boto3.Session().client('events')
stream = boto3.session.Session().client(service_name='kinesis')
db = boto3.client('dynamodb')
ssm = boto3.client('ssm')
secrets = boto3.client('secretsmanager')
def run():
    sns.publish(TopicArn='arn:aws:sns:us-east-1:123456789012:alerts')
    sns.publish_batch(TopicArn='arn:aws:sns:us-east-1:123456789012:alerts')
    bus.put_events(Entries=[{'EventBusName': 'events'}, {}])
    stream.put_record(StreamName='records')
    stream.put_records(StreamARN='arn:aws:kinesis:us-east-1:123456789012:stream/records')
    db.put_item(TableName='orders')
    db.update_item(TableName='orders')
    db.delete_item(TableName='orders')
    db.batch_write_item(RequestItems={'orders': []})
    db.transact_write_items(TransactItems=[{'Put': {'TableName': 'orders'}}, {'Delete': {'TableName': 'archive'}}])
    db.get_item(TableName='orders')
    db.query(TableName='orders')
    db.scan(TableName='orders')
    db.batch_get_item(RequestItems={'orders': {}})
    db.transact_get_items(TransactItems=[{'Get': {'TableName': 'orders'}}])
    ssm.get_parameter(Name='/orders/token')
    ssm.get_parameters(Names=['/orders/a', os.getenv('PARAMETER')])
    ssm.get_parameters_by_path(Path='/orders/')
    secrets.get_secret_value(SecretId='arn:aws:secretsmanager:us-east-1:123456789012:secret:orders/token-AbCd12')
    secrets.batch_get_secret_value(SecretIdList=['orders/a', 'orders/b'])
